package repository

import "context"

type requestKey struct{}

// WithRequestID accepts only an ID generated by the HTTP boundary, never a caller header.
func WithRequestID(ctx context.Context, id string) context.Context {
	return context.WithValue(ctx, requestKey{}, id)
}
func RequestID(ctx context.Context) string {
	id, _ := ctx.Value(requestKey{}).(string)
	return id
}

type requestUnit struct {
	Unit
	id string
}

func (u requestUnit) RequestID() string { return u.id }
func BindRequest(u Unit, ctx context.Context) Unit {
	return requestUnit{Unit: u, id: RequestID(ctx)}
}
func AuditRequestID(u Unit) string {
	if bound, ok := u.(interface{ RequestID() string }); ok && bound.RequestID() != "" {
		return bound.RequestID()
	}
	// Background operations have an independent correlation ID.
	return ID()
}
